(function(){'use strict';function init(root){if(root.dataset.hqAdReady)return;root.dataset.hqAdReady='1';const slides=[...root.querySelectorAll('[data-hm-slide]')];if(!slides.length)return;const dots=[...root.querySelectorAll('[data-hm-ad-dot]')];let active=0,timer=null;function show(index){active=(index+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===active);slide.setAttribute('aria-hidden',i===active?'false':'true');slide.querySelectorAll('a,button').forEach(el=>{if(i===active)el.removeAttribute('tabindex');else el.tabIndex=-1;});});dots.forEach((dot,i)=>{dot.classList.toggle('is-active',i===active);dot.setAttribute('aria-current',String(i===active))});}function stop(){if(timer){clearInterval(timer);timer=null}}function start(){stop();if(slides.length>1&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>show(active+1),Math.max(3500,Number(root.dataset.interval)||6500));}root.querySelector('[data-hm-ad-prev]')?.addEventListener('click',()=>{show(active-1);start()});root.querySelector('[data-hm-ad-next]')?.addEventListener('click',()=>{show(active+1);start()});dots.forEach((dot,i)=>dot.addEventListener('click',()=>{show(i);start()}));root.addEventListener('mouseenter',stop);root.addEventListener('mouseleave',start);root.addEventListener('focusin',stop);root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget))start()});document.addEventListener('visibilitychange',()=>document.hidden?stop():start());show(0);start();}document.querySelectorAll('[data-hm-ad-slider]').forEach(init);})();